#!/usr/bin/env node
/**
 * check-cloudberry-sphere — **A SPHERE-GROWN CLOUDBERRY WORLD, GENERATED BY THE GAME'S OWN
 * GENERATOR AT BUILD TIME, THROUGH THE PYTHON ROUND TRIP, PLAYED TO VICTORY** (cloudberry P2b gate).
 *
 *   CLOUDBERRY_SPHERE_DEMO_STATE (presetDefs.js: three Cloudberry levels in a chain, seed 1)
 *     → the panel's own headless run (buildRunFromState → runPresetHeadless): sphere growth, each
 *       level planned by the substrate and generated by the game page (the fetched site, headless:
 *       cloudberrySite.mjs) — TWICE, the memory cache cleared between: the same bytes;
 *     → world_generator --canonical-seed 1 → Generate.py --seed 1 (AP's fill + sphere log: winnable)
 *     → the frontend on that export (?rules=…), the Cloudberry panel:
 *
 *   1. the start level configures (the hash-checked document), same-origin;
 *   2. each level in turn: the bot collects its check coin (→ the tracker, → the item it holds is
 *      received), then walks to the end door and leaves by the forward exit (it needs the level's
 *      last piece: the item the previous level gave);
 *   3. the way back BY THE SIDE YOU CAME IN (P2b item 5): in the last level, Up at the start door
 *      offers the way back; taking it arrives in the middle level by its FORWARD exit, and there the
 *      start door offers that side (the bridge's configure.arrivedFrom) AS WELL AS the level's own
 *      way back; choosing it returns to the last level;
 *   4. the bot collects Victory: the goal is reached.
 *
 * And a MIXED world (`MIXED_STATE`: two maze regions, the start among them, and three Cloudberry levels;
 * maze keys and Cloudberry items over four spheres, one filler; loop mode on): generated the same way, the oracle holds,
 * and world_generator + Generate.py make it a winnable seed (not played here: its start is a maze room; the
 * in-app row `cloudberry-mixed-loop-bot-blocks-victory` plays the committed one in loop mode).
 *
 * Modes:
 *   (default)  the world is generated under a THROWAWAY name and removed afterwards;
 *   --write    the world is generated as the COMMITTED `cloudberry_sphere_worldgen` world + preset
 *              (worlds/cloudberry_sphere_worldgen, frontend/presets/cloudberry_sphere_worldgen) and kept, and
 *              the mixed world as the COMMITTED `cloudberry_maze_mix_worldgen` (P4a), each through its recipe
 *              in scripts/data/worldgen-package-recipes.json;
 *   --check    no play: regenerate both and compare every region's payload with the committed presets;
 *   --no-play  stop after Generate.py.
 *
 * Needs the same-origin Cloudberry site (`node scripts/setup/fetch-cloudberry-site.mjs`) and, to play,
 * a dev server serving this tree (`--port`). Screenshots: `--shots <dir>`.
 *
 *   node scripts/procgen/check-cloudberry-sphere.mjs [--port <n>] [--shots <dir>] [--keep] [--write|--check|--no-play]
 *
 * @ci-box it shells out to this tree's Python venv, `world_generator` and `Generate.py`, and needs the fetched Cloudberry site, a headless WebGL page and a dev server.
 * @tree-writes frontend/presets/preset_files.json: `Generate.py` registers the export there; the gate restores the file's bytes in its `finally` (except with --write, which keeps the committed presets' entries) — a SIGKILL skips that.
 */
import { execFileSync } from 'node:child_process';
import { createHash } from 'node:crypto';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

import { chromium } from 'playwright';

import { argvHelp, isEntryPoint } from './argvHelp.js';
import { takeBoxLockOrExit } from './boxLock.js';
import { failOnCrash, totalLine } from './gateTotal.js';
import { HEADLESS_LOGIC_ONLY_ARGS } from './headlessChromium.js';
import { generatePythonOrExit } from './repoPython.js';

argvHelp(import.meta.url);

/** The paths (up to depth 4) where two JSON values differ, for a failure message. */
function jsonDiffPaths(a, b, at = '', depth = 0, out = []) {
    if (JSON.stringify(a) === JSON.stringify(b)) return out;
    if (depth >= 4 || !a || !b || typeof a !== 'object' || typeof b !== 'object') { out.push(at || '/'); return out; }
    for (const k of new Set([...Object.keys(a), ...Object.keys(b)])) jsonDiffPaths(a[k], b[k], `${at}/${k}`, depth + 1, out);
    return out;
}

/** The first line where two texts differ: its number and both versions (a byte-level failure that JSON hides). */
function firstDifferingLine(a, b) {
    const x = a.split('\n'), y = b.split('\n');
    for (let i = 0; i < Math.max(x.length, y.length); i++) {
        if (x[i] !== y[i]) return { line: i + 1, first: x[i]?.slice(0, 160) ?? null, second: y[i]?.slice(0, 160) ?? null };
    }
    return null;
}

/**
 * ⛓ P4c FILL SLACK — the start region's FREE locations (`True_` rule) and the gem among them. Two
 * copies of a world whose start holds ONE free location box Archipelago's restrictive fill in on some
 * seeds; the committed worlds carry a second one (`Cloudberry Gem`, which opens nothing). The
 * scenario's key order puts it there.
 */
function startFreeLocations(rules) {
    const regions = rules.regions?.['1'] ?? {};
    const start = (regions.Menu?.exits ?? []).find((e) => e.name === 'GameStart')?.connected_region;
    const locs = (regions[start]?.locations ?? []).filter((l) => l.access_rule?.rule === 'True_');
    // The gem is slack only while it opens nothing: no exit or location rule may name it.
    const gates = Object.values(regions).some((r) => [...(r.exits ?? []), ...(r.locations ?? [])]
        .some((x) => JSON.stringify(x.access_rule ?? null).includes('"Cloudberry Gem"')));
    return { start, free: locs.length, gem: locs.some((l) => l.item?.name === 'Cloudberry Gem'), gates };
}
const slackOk = (rules) => {
    const s = startFreeLocations(rules);
    return { ok: s.free >= 2 && s.gem && !s.gates,
        text: `start ${s.start}: ${s.free} free locations, the gem ${s.gem ? 'among them' : 'MISSING'}, ${s.gates ? 'and it GATES something' : 'gating nothing'}` };
};

/** ⛔ NOTHING RUNS ON IMPORT (`check-procgen-help.mjs`'s import door). */
if (isEntryPoint(import.meta.url)) await main();

async function main() {
    takeBoxLockOrExit({ name: 'check-cloudberry-sphere.mjs', kind: 'browser' });

    const argv = process.argv.slice(2);
    const arg = (name) => {
        const eq = argv.find((a) => a.startsWith(`${name}=`));
        if (eq) return eq.slice(name.length + 1);
        const i = argv.indexOf(name);
        return i >= 0 ? argv[i + 1] : undefined;
    };
    const PORT = Number(arg('--port') ?? process.env.TEST_PORT ?? 8000);
    const SHOTS = arg('--shots') ? path.resolve(arg('--shots')) : null;
    const KEEP = argv.includes('--keep');
    const WRITE = argv.includes('--write');
    const CHECK = argv.includes('--check');
    const PLAY = !CHECK && !argv.includes('--no-play');

    const here = path.dirname(fileURLToPath(import.meta.url));
    const repoRoot = path.resolve(here, '../..');
    const COMMITTED = 'cloudberry_sphere_worldgen';
    const NAME = WRITE ? COMMITTED : 'cloudberry_sphere_check_worldgen';
    const GAME_NAME = WRITE ? 'Cloudberry Sphere WorldGen' : 'Cloudberry Sphere Check WorldGen';
    const WORLD_DIR = path.join(repoRoot, 'worlds', NAME);
    const PRESET_DIR = path.join(repoRoot, 'frontend/presets', NAME);
    const PRESET_FILES_JSON = path.join(repoRoot, 'frontend/presets/preset_files.json');
    const OUTPUT_DIR = path.join(repoRoot, 'output');
    const SITE_DIR = path.join(repoRoot, 'frontend/external/cloudberry');
    const SEED = 1;
    const tmpRules = path.join(repoRoot, `scripts/procgen/.${NAME}-rules.json`);
    const MIX_COMMITTED = 'cloudberry_maze_mix_worldgen';
    const MIX = WRITE ? { name: MIX_COMMITTED, game: 'Cloudberry Maze Mix WorldGen' }
        : { name: 'cloudberry_maze_mix_check_worldgen', game: 'Cloudberry Maze Mix Check WorldGen' };
    MIX.world = path.join(repoRoot, 'worlds', MIX.name);
    MIX.preset = path.join(repoRoot, 'frontend/presets', MIX.name);
    MIX.rules = path.join(repoRoot, `scripts/procgen/.${MIX.name}-rules.json`);
    const MIXED_STATE = {
        mode: 'sphereGrowth',
        // P4a: generated in LOOP MODE (loop_costs + every payload manaEnabled: Loops' maze delegation needs it), so the
        // committed world is the in-app mixed loop row's (`cloudberry-mixed-loop-bot-victory`).
        params: { seed: 1, startSubstrate: 'maze', sphereCount: 4, fillerCount: 1, enableLoopMode: true },
        // ⛓ P4c FILL SLACK: the gem is a second FREE location in the start room (see
        // CLOUDBERRY_SPHERE_DEMO_STATE). KEY ORDER load-bearing: at seed 1 it puts the gem in sphere 1 AFTER
        // Moving Blocks, and with that order the maze gates its start exit on Moving Blocks, not on the gem.
        scenario: { items: { 'Cloudberry Gem': 1, key_red: 1, 'Moving Blocks': 1, Clouds: 1, Victory: 1 }, obstacles: {} },
        substrateQuotas: { maze: 2, cloudberry: 3 },
        substrateMix: {},
        substrateMode: 'quotas',
    };
    const tmpTemplates = path.join(repoRoot, `scripts/procgen/.${NAME}-templates`);

    let failures = 0;
    failOnCrash(() => failures);
    const ok = (cond, msg) => {
        console.log(`${cond ? 'PASS' : 'FAIL'}: ${msg}`);
        if (!cond) failures++;
        return cond;
    };
    const run = (cmd, args) => execFileSync(cmd, args, { cwd: repoRoot, encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'] });
    const sha = (text) => createHash('sha256').update(text).digest('hex');

    if (!fs.existsSync(path.join(SITE_DIR, 'index.html'))) {
        console.error(`REFUSED: no Cloudberry site at ${path.relative(repoRoot, SITE_DIR)} — run: node scripts/setup/fetch-cloudberry-site.mjs`);
        process.exit(2);
    }
    const py = CHECK ? null : generatePythonOrExit('check-cloudberry-sphere.mjs');
    const presetFilesBefore = fs.existsSync(PRESET_FILES_JSON) ? fs.readFileSync(PRESET_FILES_JSON, 'utf8') : null;

    function cleanup() {
        fs.rmSync(tmpTemplates, { recursive: true, force: true });
        fs.rmSync(tmpRules, { force: true });
        fs.rmSync(MIX.rules, { force: true });
        if (CHECK) return;
        if (!WRITE) for (const p of [MIX.world, MIX.preset]) fs.rmSync(p, { recursive: true, force: true });
        if (!WRITE && presetFilesBefore !== null) fs.writeFileSync(PRESET_FILES_JSON, presetFilesBefore);
        if (fs.existsSync(OUTPUT_DIR)) {
            for (const f of fs.readdirSync(OUTPUT_DIR)) if (/^AP_\d+\.zip$/.test(f)) fs.rmSync(path.join(OUTPUT_DIR, f), { force: true });
        }
        if (WRITE || KEEP) { console.log(`[kept] ${WORLD_DIR}\n[kept] ${PRESET_DIR}`); return; }
        for (const p of [WORLD_DIR, PRESET_DIR]) fs.rmSync(p, { recursive: true, force: true });
    }

    const STOP = Symbol('stop');
    let browser = null;
    let generator = null;
    try {
        // ── Pass A: the panel's own headless run, with the game's generator ────────────
        const imp = (p) => import(pathToFileURL(path.join(repoRoot, p)));
        const { loadPipelineSubstrates } = await import('./registerPipelineSubstrates.js');
        await loadPipelineSubstrates();
        const { buildRunFromState, runPresetHeadless, heavySubstrateIds } = await imp('frontend/modules/procgenPipeline/presetRun.js');
        const { CLOUDBERRY_SPHERE_DEMO_STATE, PRESETS_SKIPPED_AS_HEAVY } = await imp('frontend/modules/procgenPipeline/presetDefs.js');
        const gen = await imp('frontend/modules/cloudberryDemo/cloudberryGeneration.js');
        const { installHeadlessCloudberryGenerator } = await import('./cloudberrySite.mjs');

        ok(JSON.stringify(heavySubstrateIds(CLOUDBERRY_SPHERE_DEMO_STATE)) === '["cloudberry"]'
            && PRESETS_SKIPPED_AS_HEAVY.includes('shipped:cloudberry-sphere-demo'),
        'the cloudberry substrate is generationCost heavy; its shipped preset is on the CI skip allowlist');

        browser = await chromium.launch({ args: [...HEADLESS_LOGIC_ONLY_ARGS] });
        let t0 = Date.now();
        generator = await installHeadlessCloudberryGenerator(browser, { cache: false, log: (m) => console.log(`  [page] ${m}`) });
        console.log(`  the generator page is ready in ${Date.now() - t0} ms (build ${generator.build})`);

        const runs = [];
        for (let i = 0; i < 2; i++) {
            gen.clearCloudberryLevelCache();
            const before = gen.cloudberryGenerationStats().generateMs.length;
            t0 = Date.now();
            // eslint-disable-next-line no-await-in-loop
            const r = await runPresetHeadless(buildRunFromState({ ...CLOUDBERRY_SPHERE_DEMO_STATE }));
            const ms = gen.cloudberryGenerationStats().generateMs.slice(before);
            runs.push({ text: JSON.stringify(r.rulesJson, null, 2), rules: r.rulesJson, oracle: r.oracleErrors, ms, total: Date.now() - t0 });
        }
        const [A, B] = runs;
        console.log(`  generation ms per level: run 1 [${A.ms.join(', ')}] (total ${A.total}), run 2 [${B.ms.join(', ')}] (total ${B.total})`);
        ok(Array.isArray(A.oracle) && A.oracle.length === 0, `Pass A: the sphere oracle holds (${JSON.stringify(A.oracle)})`);
        { const k = slackOk(A.rules); ok(k.ok, `Pass A: fill slack (P4c) — ${k.text}`); }
        ok(A.text === B.text, `Pass A: two generations from scratch give the same rules.json bytes (${sha(A.text).slice(0, 16)} / ${sha(B.text).slice(0, 16)})`);
        // A third run with the memory cache warm generates nothing.
        const warmBefore = gen.cloudberryGenerationStats().generated;
        const C = await runPresetHeadless(buildRunFromState({ ...CLOUDBERRY_SPHERE_DEMO_STATE }));
        ok(gen.cloudberryGenerationStats().generated === warmBefore && JSON.stringify(C.rulesJson, null, 2) === A.text,
            'Pass A: a re-run takes every level from the cache (nothing regenerated, same bytes)');

        const rules = A.rules;
        const sidecars = rules.preset_sidecars?.['1'] ?? {};
        const compiled = Object.fromEntries(Object.values(rules.regions).flatMap((byName) => Object.entries(byName)));
        const regionIds = Object.keys(sidecars);
        ok(regionIds.length === 3 && regionIds.every((id) => sidecars[id].substrate === 'cloudberry'),
            `Pass A: 3 regions, every one cloudberry (${regionIds.map((id) => sidecars[id].substrate).join(',')})`);
        for (const id of regionIds) {
            const p = sidecars[id].playable_payload.params;
            const pieces = p.generate.pieces.map((pc) => Object.keys(pc.upgrades).filter((u) => u !== 'Jump').join('+') || '∅');
            console.log(`  ${id}: seed ${p.generate.seed}, ${p.generate.tileset}, pieces [${pieces.join(' | ')}], `
                + `rerolls [${p.generate.rerolls}], checks ${JSON.stringify(p.checks)}, back ${p.backExitSide ?? '-'}`);
        }

        // The committed presets' payloads, compared per region: a cloudberry region by its request, document hash,
        // check coins and way back (the canonical text blanks the build); any other region by its whole payload.
        const pickPayloads = (s) => Object.fromEntries(Object.entries(s).map(([id, v]) => [id, v.substrate === 'cloudberry' ? {
            generate: v.playable_payload?.params?.generate, docSha256: v.playable_payload?.params?.docSha256,
            checks: v.playable_payload?.params?.checks, backExitSide: v.playable_payload?.params?.backExitSide ?? null,
        } : v.playable_payload]));
        const committedSidecars = (name) => {
            const presetRoot = path.join(repoRoot, 'frontend/presets', name);
            const ap = fs.existsSync(presetRoot) ? fs.readdirSync(presetRoot).find((n) => n.startsWith('AP_')) : null;
            ok(!!ap, `--check: the committed preset ${name} is present (${ap})`);
            if (!ap) return null;
            return JSON.parse(fs.readFileSync(path.join(presetRoot, ap, `${ap}_rules.json`), 'utf8')).preset_sidecars?.['1'] ?? {};
        };

        // ── The mixed world (maze + cloudberry): generated twice, oracle, Python round trip ──
        if (CHECK) {
            gen.clearCloudberryLevelCache();
            const r = await runPresetHeadless(buildRunFromState({ ...MIXED_STATE }));
            { const k = slackOk(r.rulesJson); ok(k.ok, `--check: mixed fill slack (P4c) — ${k.text}`); }
            const cs = committedSidecars(MIX_COMMITTED);
            if (cs) {
                ok(JSON.stringify(pickPayloads(cs)) === JSON.stringify(pickPayloads(r.rulesJson.preset_sidecars?.['1'] ?? {})),
                    `--check: every region's payload of the mixed world equals the committed ${MIX_COMMITTED}'s (${Object.keys(cs).length} regions)`);
            }
        } else {
            // Without --write the mixed world is a throwaway: preset_files.json is restored after it.
            const pfBeforeMix = fs.existsSync(PRESET_FILES_JSON) ? fs.readFileSync(PRESET_FILES_JSON, 'utf8') : null;
            const mixRuns = [];
            for (let i = 0; i < 2; i++) {
                gen.clearCloudberryLevelCache();
                // eslint-disable-next-line no-await-in-loop
                const r = await runPresetHeadless(buildRunFromState({ ...MIXED_STATE }));
                mixRuns.push({ text: JSON.stringify(r.rulesJson, null, 2), oracle: r.oracleErrors, rules: r.rulesJson });
            }
            const subs = Object.values(mixRuns[0].rules.preset_sidecars?.['1'] ?? {}).map((v) => v.substrate);
            ok(subs.filter((x) => x === 'maze').length >= 1 && subs.filter((x) => x === 'cloudberry').length >= 1,
                `mixed: maze and cloudberry regions in one world (${subs.join(',')})`);
            ok(Array.isArray(mixRuns[0].oracle) && mixRuns[0].oracle.length === 0, `mixed: the sphere oracle holds (${JSON.stringify(mixRuns[0].oracle)})`);
            ok(mixRuns[0].text === mixRuns[1].text, 'mixed: two generations from scratch give the same bytes');
            { const k = slackOk(mixRuns[0].rules); ok(k.ok, `mixed: fill slack (P4c) — ${k.text}`); }
            fs.writeFileSync(MIX.rules, mixRuns[0].text);
            fs.rmSync(MIX.preset, { recursive: true, force: true });
            run(py, ['-m', 'world_generator', MIX.rules, '-o', MIX.world, '--game-name', MIX.game, '--force', '--canonical-seed', '1']);
            run(py, ['-c', `from Options import generate_yaml_templates; generate_yaml_templates(${JSON.stringify(tmpTemplates)})`]);
            run(py, ['Generate.py', '--weights_file_path', path.join(tmpTemplates, `${MIX.game}.yaml`), '--multi', '1', '--seed', String(SEED)]);
            const mixAp = fs.readdirSync(MIX.preset).find((n) => n.startsWith('AP_'));
            if (WRITE) {
                // As the sphere world below: the template, and the package regenerated by its recipe FROM THE EXPORT.
                const tpl = path.join(repoRoot, 'Players/Templates', `${MIX.game}.yaml`);
                fs.copyFileSync(path.join(tmpTemplates, `${MIX.game}.yaml`), tpl);
                console.log(`  [written] ${path.relative(repoRoot, tpl)}`);
                const exportFile = path.join(MIX.preset, mixAp, `${mixAp}_rules.json`);
                const recipe = () => {
                    const recipeSource = path.join(repoRoot, `scripts/procgen/.${MIX.name}-export.json`);
                    fs.copyFileSync(exportFile, recipeSource);
                    run(py, ['-m', 'world_generator', recipeSource, '--output', MIX.world, '--game-name', MIX.game, '--force',
                        '--apply-name-substitutions', '--canonical-seed', '1']);
                    fs.rmSync(recipeSource, { force: true });
                    run(py, ['Generate.py', '--weights_file_path', path.join(tmpTemplates, `${MIX.game}.yaml`), '--multi', '1', '--seed', String(SEED)]);
                    return fs.readFileSync(exportFile, 'utf8');
                };
                const first = fs.readFileSync(exportFile, 'utf8');
                const second = recipe();
                // Measured (P4a): unlike the all-Cloudberry world, the package written from the pipeline's rules orders a
                // maze item's keys differently (`hint_text` before `id`) from the package regenerated from the export; the
                // JSON is the same. What the recipe needs is a FIXPOINT: the committed export regenerates byte for byte.
                ok(jsonDiffPaths(JSON.parse(first), JSON.parse(second)).length === 0,
                    `--write: the mixed package regenerated by its recipe exports the same JSON as the pipeline's export${
                        second === first ? ' (and the same bytes)' : ` (key order differs from line ${firstDifferingLine(first, second)?.line})`}`);
                const third = recipe();
                ok(third === second, `--write: the committed mixed export is a fixpoint of its recipe (regenerated again: the same bytes${
                    third === second ? '' : `; first differing line ${JSON.stringify(firstDifferingLine(second, third))}`})`);
            }
            const mixLog = fs.readFileSync(path.join(MIX.preset, mixAp, `${mixAp}_sphere_log.jsonl`), 'utf8');
            const mixLocs = Object.values(mixRuns[0].rules.regions['1']).flatMap((r) => r.locations ?? []).map((l) => l.name);
            ok(mixLocs.every((n) => mixLog.includes(JSON.stringify(n))) && /"Victory"/.test(
                fs.readFileSync(path.join(MIX.preset, mixAp, `${mixAp}_rules.json`), 'utf8')),
            `mixed: Generate.py makes a winnable seed (the sphere log reaches all ${mixLocs.length} locations; Victory placed)`);
            if (WRITE) {
                console.log(`[kept] ${MIX.world}\n[kept] ${MIX.preset}`);
            } else {
                if (pfBeforeMix !== null) fs.writeFileSync(PRESET_FILES_JSON, pfBeforeMix);
                for (const p of [MIX.world, MIX.preset]) fs.rmSync(p, { recursive: true, force: true });
            }
        }

        if (CHECK) {
            const cs = committedSidecars(COMMITTED);
            if (cs) {
                ok(JSON.stringify(pickPayloads(cs)) === JSON.stringify(pickPayloads(sidecars)),
                    `--check: every region's request, document hash and check coins equal the committed preset's (${Object.keys(cs).length} regions)`);
            }
            throw STOP;
        }
        fs.writeFileSync(tmpRules, A.text);

        // ── world_generator + Generate.py ─────────────────────────────────────
        fs.rmSync(PRESET_DIR, { recursive: true, force: true });
        fs.rmSync(WORLD_DIR, { recursive: true, force: true });
        run(py, ['-m', 'world_generator', tmpRules, '-o', WORLD_DIR, '--game-name', GAME_NAME, '--force', '--canonical-seed', '1']);
        run(py, ['-c', `from Options import generate_yaml_templates; generate_yaml_templates(${JSON.stringify(tmpTemplates)})`]);
        if (WRITE) {
            const tpl = path.join(repoRoot, 'Players/Templates', `${GAME_NAME}.yaml`);
            fs.copyFileSync(path.join(tmpTemplates, `${GAME_NAME}.yaml`), tpl);
            console.log(`  [written] ${path.relative(repoRoot, tpl)}`);
        }
        run(py, ['Generate.py', '--weights_file_path', path.join(tmpTemplates, `${GAME_NAME}.yaml`), '--multi', '1', '--seed', String(SEED)]);
        const apDirs = fs.readdirSync(PRESET_DIR).filter((n) => n.startsWith('AP_'));
        ok(apDirs.length === 1, `Generate.py: one AP_* export (${apDirs.join(',')})`);
        const seedId = apDirs[0];
        const exportRel = `./presets/${NAME}/${seedId}/${seedId}_rules.json`;
        const exported = JSON.parse(fs.readFileSync(path.join(PRESET_DIR, seedId, `${seedId}_rules.json`), 'utf8'));
        const exportedLocs = Object.values(exported.regions).flatMap((b) => Object.values(b)).flatMap((r) => r.locations ?? []);
        const allLocs = Object.values(compiled).flatMap((r) => r.locations ?? []).map((l) => l.name);
        ok(allLocs.every((n) => exportedLocs.some((l) => l.name === n)), `Generate.py: all ${allLocs.length} check coins exported`);
        const sphereLocs = new Set();
        for (const line of fs.readFileSync(path.join(PRESET_DIR, seedId, `${seedId}_sphere_log.jsonl`), 'utf8').split('\n').filter(Boolean)) {
            for (const pd of Object.values(JSON.parse(line).player_data ?? {})) {
                for (const l of [...(pd.new_accessible_locations ?? []), ...(pd.checked_locations ?? [])]) sphereLocs.add(l);
            }
        }
        ok(allLocs.every((n) => sphereLocs.has(n)), `Generate.py: the sphere log reaches every check coin (${sphereLocs.size}/${allLocs.length})`);
        ok(exportedLocs.some((l) => l.item?.name === 'Victory'), 'Generate.py: Victory placed (a winnable seed)');
        if (WRITE) {
            // The committed package follows its recipe (scripts/data/worldgen-package-recipes.json, the
            // freshness check's): regenerated FROM THE EXPORT with name substitutions, then exported again —
            // the preset must not move.
            const exportFile = path.join(PRESET_DIR, seedId, `${seedId}_rules.json`);
            const first = fs.readFileSync(exportFile, 'utf8');
            const recipeSource = path.join(path.dirname(tmpRules), `.${NAME}-export.json`);
            fs.copyFileSync(exportFile, recipeSource);
            run(py, ['-m', 'world_generator', recipeSource, '--output', WORLD_DIR, '--game-name', GAME_NAME, '--force',
                '--apply-name-substitutions', '--canonical-seed', '1']);
            fs.rmSync(recipeSource, { force: true });
            run(py, ['Generate.py', '--weights_file_path', path.join(tmpTemplates, `${GAME_NAME}.yaml`), '--multi', '1', '--seed', String(SEED)]);
            ok(fs.readFileSync(exportFile, 'utf8') === first,
                '--write: the package regenerated by its recipe (from the export) exports the same preset bytes');
        }
        if (!PLAY) throw STOP;

        // ── the frontend: first check to Victory ─────────────────────────────
        await generator.close();
        generator = null;
        const page = await browser.newPage({ viewport: { width: 1600, height: 1000 } });
        const logs = [];
        page.on('console', (m) => logs.push(`[${m.type()}] ${m.text()}`));
        page.on('pageerror', (e) => logs.push(`[pageerror] ${e.message}`));
        const gameSel = 'iframe[src*="/external/cloudberry/index.html"][src*="loadRegionEvent"]';
        const shot = async (name) => {
            if (!SHOTS) return;
            fs.mkdirSync(SHOTS, { recursive: true });
            await page.locator(gameSel).screenshot({ path: path.join(SHOTS, `${name}.png`) });
        };
        const base = `http://localhost:${PORT}/frontend/`;
        await page.goto(`${base}?rules=${encodeURIComponent(exportRel)}`);
        const frame = () => page.frames().find((f) => f.url().includes('/external/cloudberry/index.html') && f.url().includes('loadRegionEvent'));
        const game = (fn, a) => frame().evaluate(fn, a);
        const app = () => game(() => {
            const a = window.__cloudberryEmbed?.app;
            return a ? { region: a.config?.regionId ?? null, arrivedFrom: a.config?.arrivedFrom ?? null, refusal: a.refusal ?? null,
                play: a.playResult ?? null, checked: [...(a.checked ?? [])], events: a.events ?? [], menu: a.menu ?? null,
                startDoorSides: window.__cloudberryEmbed.startDoorSides?.() ?? null } : null;
        });
        async function waitFor(desc, fn, timeoutMs = 90000) {
            const start = Date.now();
            for (;;) {
                let v = null;
                try { v = await fn(); } catch { /* the frame may be reloading */ }
                if (v) return v;
                if (Date.now() - start > timeoutMs) {
                    console.log(logs.filter((l) => /cloudberry|flash-bridge|pageerror|error/i.test(l)).slice(-20).join('\n'));
                    throw new Error(`timeout waiting for: ${desc}`);
                }
                await page.waitForTimeout(250);
            }
        }
        const snapshot = () => page.evaluate(async () => {
            const { default: proxy } = await import('./modules/stateManager/stateManagerProxySingleton.js');
            await proxy.pingWorker('sync');
            const s = proxy.uiCache ?? {};
            const checked = s.checkedLocations;
            return { inventory: s.inventory ?? {}, checked: checked instanceof Set ? [...checked] : (Array.isArray(checked) ? checked : Object.keys(checked ?? {})) };
        });
        const walkTo = (target) => page.evaluate(async (t) => {
            const { substrateRegistry } = await import('./modules/shared/procgen/substrateRegistry.js');
            const c = substrateRegistry.get('cloudberry')?.getPlaybackController?.();
            if (!c) return false;
            c.walkTo(t);
            return true;
        }, target);
        const configured = (region) => waitFor(`${region} configured`, async () => {
            const a = await app();
            return a?.region === region && (a.play?.ok || a.refusal) ? a : null;
        }, 180000);

        // The chain, from Menu: region → its forward exit.
        const start = compiled.Menu?.exits?.[0]?.connected_region;
        const chain = [start];
        for (;;) {
            const cur = compiled[chain.at(-1)];
            const fwd = cur.exits.find((e) => !chain.includes(e.connected_region));
            if (!fwd) break;
            chain.push(fwd.connected_region);
        }
        ok(chain.length === 3, `the world is a chain of 3 levels: ${chain.join(' → ')}`);

        const a1 = await configured(start);
        ok(!a1.refusal, `1. ${start} configured and playing (${a1.refusal ?? `${a1.play.pieces} pieces, ${a1.play.checks} checks`})`);
        ok(frame().url().startsWith(base), `1. the game page is same-origin (${frame().url().split('?')[0]})`);
        await page.waitForTimeout(2500);
        await shot('1-start-level');

        const collect = async (regionId, step) => {
            for (const loc of compiled[regionId].locations) {
                if (loc.item?.name === 'Victory' || loc.item === 'Victory') continue;
                ok(await walkTo({ kind: 'location', name: loc.name }), `${step}. walkTo ${loc.name}`);
                const s = await waitFor(`${loc.name} checked`, async () => {
                    const snap = await snapshot();
                    return snap.checked.includes(loc.name) ? snap : null;
                }, 120000);
                const item = loc.item?.name ?? loc.item;
                ok(Number(s.inventory[item]) > 0, `${step}. ${loc.name} checked → ${item} received`);
            }
        };
        const leave = async (regionId, toRegion, step) => {
            const exit = compiled[regionId].exits.find((e) => e.connected_region === toRegion);
            ok(await walkTo({ kind: 'exit', name: exit.name }), `${step}. walkTo ${exit.name} (needs ${JSON.stringify(exit.access_rule)})`);
            const a = await configured(toRegion);
            ok(!a.refusal && a.region === toRegion, `${step}. the bot left by the end door → ${toRegion} configured`);
            return a;
        };
        const startDoor = async (choose) => {
            await game(() => window.__cloudberryEmbed.rearmDoors());
            await frame().locator('canvas').first().click({ position: { x: 5, y: 5 } }).catch(() => {});
            await page.keyboard.down('ArrowUp');
            const menu = await waitFor('the start door menu opens on Up', async () => ((await app()).menu ?? null), 10000).catch(() => null);
            await page.keyboard.up('ArrowUp');
            const entries = await game(() => [...document.querySelectorAll('button, [role=button], div')]
                .map((el) => el.textContent ?? '').filter((t) => /\b(north|east|south|west)\b|↑|→|↓|←/.test(t)).slice(-8));
            await page.waitForTimeout(400);
            if (choose) await page.keyboard.press({ north: 'ArrowUp', east: 'ArrowRight', south: 'ArrowDown', west: 'ArrowLeft' }[choose]);
            return { menu, entries };
        };

        // 2. each level: its check coin, then out by the forward exit.
        await collect(chain[0], '2a');
        const a2 = await leave(chain[0], chain[1], '2a');
        ok((a2.startDoorSides ?? []).length >= 1, `2a. in ${chain[1]} the start door offers the way back (${JSON.stringify(a2.startDoorSides)}, arrived by ${JSON.stringify(a2.arrivedFrom)})`);
        await page.waitForTimeout(1500);
        await shot('2-second-level');
        await collect(chain[1], '2b');
        const a3 = await leave(chain[1], chain[2], '2b');
        ok(!!a3.arrivedFrom, `2b. the bridge passed arrivedFrom (${JSON.stringify(a3.arrivedFrom)})`);

        // 3. the start door: back by the side we came in, then forward again by the side we came in.
        const back = await startDoor(null);
        ok(back.menu?.door === 'start', `3. Up at the start door of ${chain[2]} opened the way-back menu (${JSON.stringify(back.menu)})`);
        await shot('3-start-door-menu');
        const backSide = a3.startDoorSides?.[0];
        await page.keyboard.press({ north: 'ArrowUp', east: 'ArrowRight', south: 'ArrowDown', west: 'ArrowLeft' }[backSide]);
        const a4 = await configured(chain[1]);
        const fwdExit = compiled[chain[1]].exits.find((e) => e.connected_region === chain[2]);
        const fwdSide = sidecars[chain[1]].playable_payload.exits?.find?.((e) => e.exit_id === fwdExit.name.split('__').pop())?.side;
        const PAGE = { N: 'north', E: 'east', S: 'south', W: 'west' };
        const backSideMid = PAGE[sidecars[chain[1]].playable_payload.params.backExitSide];
        ok(a4.region === chain[1] && (a4.startDoorSides ?? []).includes(PAGE[fwdSide]) && (a4.startDoorSides ?? []).includes(backSideMid),
            `3. back in ${chain[1]} by its ${PAGE[fwdSide]} exit: the start door offers ${JSON.stringify(a4.startDoorSides)} `
            + `(the side arrived by ${PAGE[fwdSide]} + the way back ${backSideMid}; arrivedFrom ${JSON.stringify(a4.arrivedFrom)})`);
        const again = await startDoor(null);
        ok(again.menu?.door === 'start', `3. Up at the start door of ${chain[1]} opened the menu (${JSON.stringify(again.menu)})`);
        await page.waitForTimeout(300);
        await shot('4-start-door-two-ways');
        await page.keyboard.press({ north: 'ArrowUp', east: 'ArrowRight', south: 'ArrowDown', west: 'ArrowLeft' }[PAGE[fwdSide]]);
        const a5 = await configured(chain[2]);
        ok(a5.region === chain[2], `3. → ${PAGE[fwdSide]} at the start door returned to ${chain[2]}`);

        // 4. Victory.
        const victory = compiled[chain[2]].locations.find((l) => (l.item?.name ?? l.item) === 'Victory');
        ok(!!victory, `4. ${chain[2]} holds Victory (${victory?.name})`);
        ok(await walkTo({ kind: 'location', name: victory.name }), `4. walkTo ${victory.name}`);
        const sv = await waitFor('Victory received', async () => {
            const s = await snapshot();
            return Number(s.inventory.Victory) > 0 ? s : null;
        }, 120000);
        ok(Number(sv.inventory.Victory) > 0, `4. Victory collected: every check (${sv.checked.length}/${allLocs.length})`);
        await page.waitForTimeout(1500);
        await shot('5-victory');

        const errors = logs.filter((l) => l.startsWith('[pageerror]') && !l.includes('unwind'));
        ok(errors.length === 0, `no page errors (${errors.slice(0, 3).join(' | ')})`);
    } catch (err) {
        if (err !== STOP) ok(false, `crashed: ${err.stack ?? err}`);
    } finally {
        if (generator) await generator.close().catch(() => {});
        if (browser) await browser.close();
        cleanup();
    }
    console.log(failures === 0 ? '\nAll cloudberry sphere assertions passed.' : `\n${failures} assertion(s) FAILED.`);
    console.log(totalLine(failures));
    process.exit(failures === 0 ? 0 : 1);
}
